export default function prepare({ events }) {
  if (!Array.isArray(events) || events.length === 0) throw Error("No new rows");
  const row = events[events.length - 1].row,
    date = row["Event Start Date"],
    year = new Date().getFullYear();
  if (typeof date !== "string") throw Error("Event Start Date must be text");
  const d = new Date((date.includes(String(year)) ? date : `${date} ${year}`) + " UTC");
  if (!Number.isFinite(d.getTime())) throw Error("Invalid event date");
  const start = d.toISOString().slice(0, 10),
    end = new Date(Date.parse(start) + 86400000).toISOString().slice(0, 10);
  return {
    event: {
      summary: row["Event Name"],
      description: row["Event Description"],
      location: row.Location,
      start: { date: start },
      end: { date: end },
      colorId: "3",
      transparency: "transparent",
    },
  };
}
